    /**
     * Resolve which record this imported row maps to (generated custom logic).
     * @return  ?Pelajar  Resolved record instance.
     */
    public function resolveRecord(): ?Pelajar
    {
    
        return Pelajar::firstOrNew([
            'no_matrik' => $this->data['no_matrik']
        ]);
    }

    /**
     * Notification body shown when the import finishes.
     *
     * @param  Import  $import  The completed import job.
     * @return  string  Human-readable completion summary.
     */
    public static function getCompletedNotificationBody(Import $import): string
    {
        $body = 'Your Pelajar import has completed and ' . Number::format($import->successful_rows) . ' ' . str('row')->plural($import->successful_rows) . ' imported.';

        if ($failedRowsCount = $import->getFailedRowsCount()) {
            $body .= ' ' . Number::format($failedRowsCount) . ' ' . str('row')->plural($failedRowsCount) . ' failed to import.';
        }

        return $body;
    }
    
